INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Ausbildungsvergütung gesetzlich vorgeschrieben?', 2, '[{"text": "Nein", "correct": true, "because": "Mindestlohn als Minimum, sonst frei"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Ausbildungsvergütung?', 3, '[{"text": "Auszubildende finanziell unterstützen", "correct": true, "because": "Lebensunterhalt sichern"}, {"text": "Kosten senken", "correct": false, "because": "Nicht primär"}, {"text": "Produktivität steigern", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Ausbildungsvergütung?', 5, '[{"text": "Grundvergütung", "correct": true, "because": "Basiseinkommen"}, {"text": "Zuschläge", "correct": true, "because": "z.B. Schichtarbeit"}, {"text": "Urlaubsanspruch", "correct": false, "because": "Kein Vergütungselement"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Ausbildungsvergütung steigt oft mit dem Ausbildungsjahr. b) Sie ist immer gleich hoch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Höhe variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Ausbildungsvergütung?', 4, '[{"text": "Tarifverträge", "correct": false, "because": "Oft Grundlage"}, {"text": "Mindestlohn", "correct": false, "because": "Gesetzliches Minimum"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Ausbildungsvergütung tariflich geregelt sein kann?', 2, '[{"text": "Ja", "correct": true, "because": "Häufig tarifgebunden"}, {"text": "Nein", "correct": false, "because": "Tarifverträge üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regelung beeinflusst die Ausbildungsvergütung?', 3, '[{"text": "Mindestlohngesetz", "correct": true, "because": "Setzt Untergrenze"}, {"text": "Urlaubsgesetz", "correct": false, "because": "Kein Vergütungsbezug"}, {"text": "Steuergesetz", "correct": false, "because": "Nachgelagert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Berechnung der Ausbildungsvergütung?', 5, '[{"text": "Ausbildungsjahr", "correct": true, "because": "Steigt oft jährlich"}, {"text": "Tarifvertrag", "correct": true, "because": "Regelt Höhe"}, {"text": "Büroausstattung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Ausbildungsvergütung ist steuerfrei. b) Sie ist immer tariflich geregelt. Stimmt das?', 3, '[{"text": "Keines stimmt", "correct": true, "because": "Steuerpflichtig, nicht immer Tarif"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Ausbildungsvergütung unwichtig?', 4, '[{"text": "Ausbildungsjahr", "correct": false, "because": "Beeinflusst Höhe"}, {"text": "Tarifvereinbarung", "correct": false, "because": "Regelt Vergütung"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss die Ausbildungsvergütung monatlich gezahlt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Übliche Praxis"}, {"text": "Nein", "correct": false, "because": "Gesetzlich üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine faire Ausbildungsvergütung?', 4, '[{"text": "Motivation", "correct": true, "because": "Fördert Engagement"}, {"text": "Attraktivität", "correct": true, "because": "Lockt Talente"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Ausbildungsvergütung immer niedrig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Variiert nach Branche"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Ausbildungsvergütung?', 3, '[{"text": "Fairness", "correct": true, "because": "Motiviert Auszubildende"}, {"text": "Kostenreduktion", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Ausbildungsvergütung ist steuerpflichtig. b) Sie ist immer gleich hoch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Höhe variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine zu niedrige Ausbildungsvergütung?', 5, '[{"text": "Geringe Motivation", "correct": true, "because": "Wenig Anreiz"}, {"text": "Weniger Bewerber", "correct": true, "because": "Unattraktiv"}, {"text": "Höhere Produktivität", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Ausbildungsvergütung unwichtig?', 3, '[{"text": "Mindestlohn", "correct": false, "because": "Gesetzliche Grenze"}, {"text": "Tarifvertrag", "correct": false, "because": "Regelt oft Höhe"}, {"text": "Bürodesign", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die Ausbildungsvergütung Zuschläge enthalten?', 3, '[{"text": "Ja", "correct": true, "because": "z.B. Schichtzuschläge"}, {"text": "Nein", "correct": false, "because": "Möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Ausbildungsvergütung gesetzlich steuerfrei ist?', 2, '[{"text": "Nein", "correct": true, "because": "Steuerpflichtig"}, {"text": "Ja", "correct": false, "because": "Steuerpflicht gilt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regel wähle ich für die Ausbildungsvergütung?', 4, '[{"text": "Mindestlohngesetz", "correct": true, "because": "Setzt Minimum"}, {"text": "Urlaubsgesetz", "correct": false, "because": "Kein Vergütungsbezug"}, {"text": "Marketingplan", "correct": false, "because": "Irrelevant"}]');
